package app.lockdin

import app.lockdin.engine.OverrideRecord
import app.lockdin.engine.OverrideScope
import app.lockdin.engine.OverrideState
import app.lockdin.engine.PhaseKind
import app.lockdin.engine.Segment
import app.lockdin.engine.Session
import app.lockdin.engine.SessionControls
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Test

/** Every sample generated by core/examples/parity_vectors.rs must match the Kotlin port exactly. */
class SessionParityTest {
    private val t0 = java.time.Instant.parse("2026-11-03T18:00:00Z").toEpochMilli()
    private fun s(sec: Long) = t0 + sec * 1000

    @Test
    fun matchesRustCoreOnEveryVector() {
        val text = javaClass.classLoader!!.getResource("parity-vectors.json")!!.readText()
        val cases = JSONObject(text).getJSONArray("cases")
        var samples = 0
        for (i in 0 until cases.length()) {
            val c = cases.getJSONObject(i)
            val segs = c.getJSONArray("segments").let { a ->
                (0 until a.length()).map { a.getJSONObject(it) }.map {
                    Segment(PhaseKind.valueOf(it.getString("kind").uppercase()), it.getInt("minutes"))
                }
            }
            val ctl = c.getJSONObject("controls")
            val overrides = ctl.getJSONArray("overrides").let { a ->
                (0 until a.length()).map { a.getJSONObject(it) }.map {
                    OverrideRecord(
                        id = it.getString("id"),
                        scope = OverrideScope.valueOf(it.getString("scope").uppercase()),
                        phaseIndex = it.getInt("phase_index"),
                        requestedAt = s(it.getLong("requested_at")),
                        delaySeconds = it.getInt("delay_seconds"),
                        cancelledAt = if (it.isNull("cancelled_at")) null else s(it.getLong("cancelled_at")),
                    )
                }
            }
            val controls = SessionControls(overrides, if (ctl.isNull("emergency_recovery")) null else s(ctl.getLong("emergency_recovery")))
            val occ = Session.occurrenceFrom(t0, segs)
            val list = c.getJSONArray("samples")
            for (j in 0 until list.length()) {
                val v = list.getJSONObject(j)
                val t = v.getLong("t")
                val snap = Session.evaluate(occ, controls, s(t))
                val where = "${c.getString("name")} @ t=$t"
                assertEquals(where, v.getString("status"), snap.status.name.lowercase())
                assertEquals(where, v.getBoolean("restricting"), snap.restricting)
                assertEquals(where, if (v.isNull("release_reason")) null else v.getString("release_reason"), snap.releaseReason?.name?.lowercase())
                assertEquals(where, if (v.isNull("phase_index")) null else v.getInt("phase_index"), snap.phase?.index)
                assertEquals(where, if (v.isNull("next_transition")) null else v.getLong("next_transition"), snap.nextTransition?.let { (it - t0) / 1000 })
                val ov = v.getJSONObject("override_state")
                when (val o = snap.overrideState) {
                    OverrideState.None -> assertEquals(where, "none", ov.getString("type"))
                    is OverrideState.Pending -> {
                        assertEquals(where, "pending", ov.getString("type"))
                        assertEquals(where, ov.getString("scope"), o.scope.name.lowercase())
                        assertEquals(where, ov.getLong("effective_at"), (o.effectiveAt - t0) / 1000)
                    }
                    is OverrideState.ActiveForFocusPeriod -> {
                        assertEquals(where, "active_for_focus_period", ov.getString("type"))
                        assertEquals(where, ov.getLong("until"), (o.until - t0) / 1000)
                    }
                }
                samples++
            }
        }
        assertEquals(773, samples)
    }

    @Test
    fun plansMatchCoreRules() {
        assertEquals(
            listOf(Segment(PhaseKind.FOCUS, 40), Segment(PhaseKind.BREAK, 10), Segment(PhaseKind.FOCUS, 40)),
            Session.roundsPlan(2, 40, 10),
        )
        assertNotNull(Session.validatePlan(emptyList()))
        assertNotNull(Session.validatePlan(listOf(Segment(PhaseKind.BREAK, 5))))
        assertNotNull(Session.validatePlan(listOf(Segment(PhaseKind.FOCUS, 241))))
        assertNotNull(Session.validatePlan(Session.roundsPlan(4, 240, 120)))
        assertNull(Session.validatePlan(Session.roundsPlan(2, 40, 10)))
    }
}
